package com.gameaggregator.releaseservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.releaseservice.application.ReleaseService;import com.gameaggregator.releaseservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/releases") public class ReleaseController{final ReleaseService s;public ReleaseController(ReleaseService s){this.s=s;}@PostMapping ApiResponse<Release> create(@Valid @RequestBody ReleaseDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<Release>> list(@RequestParam(required=false)UUID gameId){return ApiResponse.success(s.list(gameId));}@GetMapping("/{id}")ApiResponse<Release> get(@PathVariable UUID id){return ApiResponse.success(s.get(id));}@PutMapping("/{id}/notes")ApiResponse<Release> notes(@PathVariable UUID id,@Valid @RequestBody ReleaseDtos.Notes r){return ApiResponse.success(s.notes(id,r));}@PostMapping("/{id}/submit")ApiResponse<Release> submit(@PathVariable UUID id){return ApiResponse.success(s.submit(id));}@PostMapping("/{id}/approve")ApiResponse<Release> approve(@PathVariable UUID id,@Valid @RequestBody ReleaseDtos.Decision r){return ApiResponse.success(s.approve(id,r));}@PostMapping("/{id}/reject")ApiResponse<Release> reject(@PathVariable UUID id,@Valid @RequestBody ReleaseDtos.Decision r){return ApiResponse.success(s.reject(id,r));}@PostMapping("/{id}/publish")ApiResponse<Release> publish(@PathVariable UUID id,@Valid @RequestBody ReleaseDtos.Publish r){return ApiResponse.success(s.publish(id,r));}@PostMapping("/{id}/rollback")ApiResponse<Release> rollback(@PathVariable UUID id,@Valid @RequestBody ReleaseDtos.Rollback r){return ApiResponse.success(s.rollback(id,r));}@GetMapping("/{id}/decisions")ApiResponse<List<ReleaseDecision>> decisions(@PathVariable UUID id){return ApiResponse.success(s.decisions(id));}}